sp_widget.client_script:
function($location) {
  var c = this;
  /* I6: Idea-lifecycle states. Happy path 1 -> -1 -> 2 -> 4 -> 5 -> 3;
     -2 renders as an attention node; 7/8/9 as terminal branches. */
  var SLUGS = {'1': 'submitted', '-2': 'need_info', '-1': 'under_review', '2': 'in_backlog',
               '4': 'planned', '5': 'in_development', '3': 'completed', '7': 'unlikely',
               '9': 'cancelled', '8': 'duplicate'};
  var STEPS = [
    { v: '1',  t: 'Submitted',      s: 'Request received and queued for triage.' },
    { v: '-1', t: 'Under Review',   s: 'PTAG is validating scope and fit.' },
    { v: '2',  t: 'In Backlog',     s: 'Accepted and waiting for capacity.' },
    { v: '4',  t: 'Planned',        s: 'Scheduled with an owner and a timeline.' },
    { v: '5',  t: 'In Development', s: 'Work in flight with the assigned team.' },
    { v: '3',  t: 'Completed',      s: 'Engagement delivered and closed.' }
  ];
  var TERMINAL = {
    '7': { t: 'Unlikely to implement', s: 'Not moving forward after PTAG review.', pred: 2 },
    '8': { t: 'Duplicate',             s: 'Already tracked under another request.', pred: 2 },
    '9': { t: 'Cancelled',             s: 'Withdrawn before completion.', pred: 1 }
  };

  c.number = '';
  c.busy = false;
  c.nodes = [];

  function decorate() {
    c.nodes = [];
    var rec = c.data && c.data.rec;
    if (!rec) { return; }
    var st = String(rec.state || '1');
    rec.slug = SLUGS[st] || 'submitted';
    rec.created_d = String(rec.created || '').split(' ')[0];
    var i;
    if (TERMINAL[st]) {
      for (i = 0; i < TERMINAL[st].pred; i++) {
        c.nodes.push({ t: STEPS[i].t, s: STEPS[i].s, cls: 'is-done', neg: false, attn: false });
      }
      c.nodes.push({ t: TERMINAL[st].t, s: TERMINAL[st].s, cls: 'is-negative', neg: true, attn: false });
      return;
    }
    if (st === '-2') {
      /* attention: review is paused on the requester */
      c.nodes.push({ t: STEPS[0].t, s: STEPS[0].s, cls: 'is-done', neg: false, attn: false });
      c.nodes.push({ t: STEPS[1].t, s: STEPS[1].s, cls: 'is-done', neg: false, attn: false });
      c.nodes.push({ t: 'Need more information', s: 'PTAG is waiting on you - check your email and update the request.', cls: 'is-attn', neg: false, attn: true });
      for (i = 2; i < STEPS.length; i++) {
        c.nodes.push({ t: STEPS[i].t, s: STEPS[i].s, cls: 'is-future', neg: false, attn: false });
      }
      return;
    }
    var pos = 0;
    for (i = 0; i < STEPS.length; i++) { if (STEPS[i].v === st) { pos = i; break; } }
    for (i = 0; i < STEPS.length; i++) {
      var cls = (i < pos) ? 'is-done' : ((i === pos) ? 'is-current' : 'is-future');
      if (st === '3') { cls = 'is-done'; }
      c.nodes.push({ t: STEPS[i].t, s: STEPS[i].s, cls: cls, neg: false, attn: false });
    }
  }

  c.lookup = function() {
    var n = String(c.number || '').toUpperCase().replace(/\s+/g, '');
    if (!n || c.busy) { return; }
    c.number = n;
    c.busy = true;
    c.server.get({ number: n }).then(function(r) {
      c.data.searched = r.data.searched;
      c.data.found = r.data.found;
      c.data.rec = r.data.rec;
      decorate();
      c.busy = false;
    }, function() { c.busy = false; });
  };

  /* auto-lookup when the page carries ?number= (submit receipt / My Engagements) */
  var q = {};
  try { q = $location.search() || {}; } catch (e) {}
  var n0 = q.number || '';
  if (!n0) {
    try {
      var m = (window.location.search || '').match(/[?&]number=([^&]+)/);
      if (m) { n0 = decodeURIComponent(m[1]); }
    } catch (e2) {}
  }
  if (n0) { c.number = String(n0); c.lookup(); }
}

sp_widget.script:
(function() {
  /* I6: logged-in lookup by PTAG number. Access enforced HERE (server side):
       - requester sees records they opened (opened_by = session user)
       - x_snc_ptag_engage.user / x_snc_ptag_engage.admin see all
         (gs.hasRole also returns true for admins - intended)
     status_token stays in the schema, dormant; there is no token path.
     Anti-enumeration posture kept: exact-match single record, {found:false}
     on any miss, whitelisted payload only, no record sys_ids. */
  data.found = false;
  data.searched = false;
  if (!gs.getSession().isLoggedIn()) { return; }
  if (!input || !input.number) { return; }
  data.searched = true;

  var num = String(input.number).toUpperCase().replace(/\s+/g, '');
  if (!/^PTAG\d{4,12}$/.test(num)) { return; }

  var canSeeAll = gs.hasRole('x_snc_ptag_engage.user') || gs.hasRole('x_snc_ptag_engage.admin');
  var gr = new GlideRecord('x_snc_ptag_engage_engagement_request');
  gr.addQuery('number', num);
  if (!canSeeAll) { gr.addQuery('opened_by', gs.getUserID()); }
  gr.setLimit(1);
  gr.query();
  if (!gr.next()) { return; }

  /* WHITELIST ONLY - never widen without a security review */
  data.found = true;
  data.rec = {
    number: gr.getValue('number'),
    state: String(gr.getValue('state') || '1'),
    state_label: gr.getDisplayValue('state'),
    practice: gr.getDisplayValue('practice'),
    route_to_market: gr.getDisplayValue('route_to_market'),
    partner_name: gr.getDisplayValue('partner'),
    short_description: gr.getValue('short_description'),
    assigned_to: gr.getDisplayValue('assigned_to'),
    created: gr.getDisplayValue('sys_created_on'),
    updated: gr.getDisplayValue('sys_updated_on')
  };
})();
